// LeetCode 380 — a set with Insert, Remove and GetRandom, each O(1) on average.
public sealed class RandomizedSet {
    private readonly List<int> _items = new List<int>();               // the values, packed with no gaps
    private readonly Dictionary<int, int> _index = new Dictionary<int, int>();   // value -> position in _items
    private readonly Random _rnd;

    public RandomizedSet() : this(new Random()) { }
    public RandomizedSet(Random rnd) { _rnd = rnd; }

    public bool Insert(int val) {
        if (_index.ContainsKey(val)) return false;
        _index[val] = _items.Count;
        _items.Add(val);
        return true;
    }

    public bool Remove(int val) {
        if (!_index.TryGetValue(val, out int pos)) return false;
        // Removing from the middle of a list is O(n). Instead, move the LAST value into the hole,
        // then remove the last slot, which is O(1).
        int last = _items[_items.Count - 1];
        _items[pos] = last;
        _index[last] = pos;
        _items.RemoveAt(_items.Count - 1);
        _index.Remove(val);
        return true;
    }

    public int GetRandom() {
        if (_items.Count == 0) throw new InvalidOperationException("the set is empty");
        return _items[_rnd.Next(_items.Count)];      // packed list: every value equally likely
    }

    public int Count => _items.Count;
}
